def make_task(
    id: int = 1,
    title: str = "Test task",
    status: TaskStatus = TaskStatus.PENDING,
    priority: TaskPriority = TaskPriority.MEDIUM,
    due_at=None,
    completed_at=None,
    created_at=None,
    tags=None,
) -> Task:
    return Task(
        id=id,
        title=title,
        status=status,
        priority=priority,
        due_at=due_at,
        completed_at=completed_at,
        created_at=created_at or FIXED_NOW,
